require_once __DIR__.'/../includes/functions.php';admin_required();$items=[];try{$items=db()->query('SELECT r.*,i.slug FROM rsvps r JOIN invitations i ON i.id=r.invitation_id ORDER BY r.created_at DESC')->fetchAll();}catch(Throwable){}$page_title='RSVP';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">GUESTS</span><h1>RSVP masuk</h1></header><section class="table-wrap"><table><thead><tr><th>Nama</th><th>WhatsApp</th><th>Kehadiran</th><th>Jumlah</th><th>Invitation</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['guest_name'])?></td><td><?=e($item['whatsapp']??'-')?></td><td><?=e($item['attendance'])?></td><td><?=e((string)$item['guest_count'])?></td><td><?=e($item['slug'])?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Belum ada RSVP.</td></tr><?php endif;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
